/* Кушетка — документы для поискового индекса: книга в приложении, каталог, справочник, свои материалы. */
window.KLibDocs = (function(){
"use strict";
function build(D, L, extra){
  extra = extra || {};
  const docs = [], SPH = L.SPH;
  const osap = L.osap;
  if (osap) osap.ch.forEach((c, ci) => {
    const sph = L.osapSph[c.n] || ["anat"];
    c.s.forEach((s, si) => {
      docs.push({kind: "sec", src: "osap", ci, si, title: s.t + " " + s.r, kw: s.o.join(" ") + " " + s.g.map(g => g[0]).join(" ") + " " + c.t + " " + c.r, body: "", sph, lang: "en", prior: 1.15});
      let head = "";
      for (let bi = 0; bi < s.b.length; bi++){
        const [k, t] = s.b[bi];
        if (k === "h" || k === "N"){ head = t; continue; }
        if (k === "l"){
          let txt = t, n = 1;
          while (bi + n < s.b.length && s.b[bi + n][0] === "l" && txt.length < 900){ txt += " " + s.b[bi + n][1]; n++; }
          docs.push({kind: "para", src: "osap", ci, si, bi, n, title: head, body: txt, sph, lang: "en", prior: 1});
          bi += n - 1; continue;
        }
        docs.push({kind: "para", src: "osap", ci, si, bi, n: 1, title: head, body: t, sph, lang: "en", prior: k === "c" ? 0.85 : 1});
      }
      s.g.forEach((g, gi) => docs.push({kind: "gloss", src: "osap", ci, si, gi, title: g[0], body: g[1], sph, lang: "en", prior: 1}));
    });
  });
  L.books.forEach(b => {
    docs.push({kind: "book", id: b.id, title: b.t + " " + b.r, kw: [b.kw, b.type, b.a, (b.sph || []).map(x => SPH[x]).join(" ")].join(" "), body: [b.about, b.use, b.ru || ""].join(" "), sph: b.sph, lang: b.lang, acc: b.acc, prior: 1.05});
    (b.ch || []).forEach((ch, idx) => docs.push({kind: "chap", id: b.id, idx, title: ch[1] + " " + ch[2], kw: b.r, body: "", sph: b.sph, lang: b.lang, acc: b.acc, url: ch[0], prior: 1}));
  });
  const regName = k => { const r = D.REGIONS.find(x => x.k === k); return r ? r.name : ""; };
  D.TESTS.forEach(t => docs.push({kind: "ref", sub: "tests", key: t.k, title: t.name, kw: "тест проба " + D.REGIONS.filter(r => r.tests.indexOf(t.k) >= 0).map(r => r.name).join(" "), body: [t.how, t.pos, t.mean, t.src].join(" "), sph: ["mass", "rehab"], lang: "ru", prior: 1.2}));
  D.TECH.forEach(t => docs.push({kind: "ref", sub: "tech", key: t.k, title: t.name, kw: "приём техника", body: [t.how, t.dose, t.src].join(" "), sph: ["mass"], lang: "ru", prior: 1.2}));
  Object.keys(D.LINES).forEach(k => docs.push({kind: "ref", sub: "lines", key: k, title: D.LINES[k].name, kw: "линия Майерса анатомические поезда миофасциальная линия", body: D.LINES[k].path, sph: ["mass", "anat"], lang: "ru", prior: 1.1}));
  D.REGIONS.forEach(r => docs.push({kind: "ref", sub: "regions", key: r.k, title: r.name, kw: r.muscles.join(" ") + " зона регион", body: [r.home.join(" "), r.flags.join(" "), r.lit.join(" ")].join(" "), sph: ["mass", "rehab"], lang: "ru", prior: 1.15}));
  D.LABS.forEach(d => docs.push({kind: "ref", sub: "labs", key: d.k, title: d.name, kw: "анализ показатель " + d.unit, body: Object.values(d.t || {}).join(" "), sph: ["med"], lang: "ru", prior: 1.15}));
  D.LAB_DERIVED.forEach(d => docs.push({kind: "ref", sub: "labs", key: d.k, title: d.name, kw: "анализ индекс " + d.from, body: Object.values(d.t || {}).join(" "), sph: ["med"], lang: "ru", prior: 1.15}));
  D.DIETS.forEach(d => { const i = D.DIET_INFO[d.k] || {}; docs.push({kind: "ref", sub: "diets", key: d.k, title: d.name + " питание диета", kw: d.short, body: [i.idea, (i.yes || []).join(" "), (i.limit || []).join(" "), (i.tips || []).join(" ")].join(" "), sph: ["nutr"], lang: "ru", prior: 1.1}); });
  D.EX.forEach(e => docs.push({kind: "ref", sub: "ex", key: e.id, title: e.n, kw: "упражнение " + (D.PAT_NAMES[e.pat] || ""), body: e.note || "", sph: ["train"], lang: "ru", prior: 0.9}));
  D.AUTHORS.forEach(a => docs.push({kind: "ref", sub: "authors", key: a.k, title: a.name, kw: a.role, body: [a.about, a.inApp, a.read.join(" ")].join(" "), sph: ["train", "mass"], lang: "ru", prior: 1.05}));
  D.LIB.forEach((x, i) => docs.push({kind: "course", key: i, title: x.t, kw: x.kind + " " + (D.TOPICS[x.topic] || ""), body: x.note, sph: [({massage: "mass", kin: "mass", train: "train", food: "nutr", anat: "anat"})[x.topic] || "mass"], lang: /[а-я]/i.test(x.t) ? "ru" : "en", url: x.url, free: x.free, prior: 1}));
  (extra.methods || []).forEach(m => docs.push({kind: "ref", sub: "methods", key: m.key, title: m.name, kw: m.by + " методика тренировок", body: [m.about, (m.rules || []).join(" ")].join(" "), sph: ["train"], lang: "ru", prior: 1.1}));
  (extra.pit || []).forEach(e => docs.push({kind: "ref", sub: "pit", key: e.id, title: e.n + " " + e.o, kw: [e.cn, e.sc, e.or, "питание", e.ais ? "добавка AIS " + e.ais : ""].join(" "), body: [e.d, e.pr, e.fn || "", e.fs || "", e.ind, e.pn].join(" "), sph: ["nutr"], lang: "ru", prior: 1.1}));
  const MSZ = {head: "голова", face: "лицо", neck: "шея", shoulders: "надплечья плечевой пояс", upper_back: "спина лопатки", lower_back: "поясница", sacrum: "крестец", glutes: "ягодицы", thigh_back: "бедро задняя поверхность", thigh_front: "бедро квадрицепс", knee: "колено", calf: "икры голень", shin: "голень", foot: "стопа", arm: "плечо рука", forearm: "предплечье", hand: "кисть", chest: "грудь", abdomen: "живот", whole_body: "всё тело"};
  (extra.massage || []).forEach(e => docs.push({kind: "ref", sub: "mass", key: e.id, title: e.n + " " + e.o, kw: [e.cn, e.sc, e.or, e.ay, "массаж методика техника"].concat(e.z.p, e.z.s, (e.sn.zones_primary || []).map(z => MSZ[z] || "")).join(" "), body: [e.d, e.g, e.pr, e.ind, e.st.join(" ")].join(" "), sph: ["mass"], lang: "ru", prior: 1.1}));
  (extra.trainings || []).forEach(e => docs.push({kind: "ref", sub: "train", key: e.id, title: e.n + " " + e.o, kw: [e.cn, e.sc, e.or, e.ay, "тренировка методика"].concat(e.mu ? e.mu.p.concat(e.mu.s) : []).join(" "), body: [e.d, e.g, e.pr, e.ind].join(" "), sph: ["train"], lang: "ru", prior: 1.1}));
  (extra.mine || []).forEach((x, i) => docs.push({kind: "mine", key: x.id, title: x.t, kw: x.kw || "", body: x.note || "", sph: x.sph ? [x.sph] : [], lang: /[а-я]/i.test(x.t) ? "ru" : "en", url: x.url, prior: 1.2}));
  return docs;
}
return {build};
})();

