/* Кушетка: перевод на русский прямо на устройстве (Windows-версия).
   Движок — Bergamot Translator (Mozilla, MPL-2.0), модели — Mozilla Firefox Translations: en→ru и,
   для книг на французском, немецком, испанском, итальянском, португальском и украинском, X→en
   (перевод идёт через английский: движок сам сцепляет две модели).
   Программа-оболочка поднимает помощника на 127.0.0.1 и сообщает адрес через window.kushetkaMT.
   В веб-версии помощника нет, и KMT.on === false.
   iPhone-версия (веб-приложение): помощника изображает service worker (ios/sw.js) по тем же адресам,
   cfg.ios = true; файлы движка и модели страница сама читает и передаёт рабочему потоку как blob: —
   так не важно, подчиняется ли service worker'у поток, созданный из blob. */
window.KMT = (function(){
  const cfg = window.kushetkaMT || null;
  const on = !!(cfg && cfg.base && cfg.token);
  function url(p, q){
    let u = cfg.base + p + "?t=" + encodeURIComponent(cfg.token);
    if (q) Object.keys(q).forEach(k => { u += "&" + k + "=" + encodeURIComponent(q[k]); });
    return u;
  }
  async function errText(r){ const t = await r.text().catch(() => ""); return (t || "").trim().slice(0, 300) || ("ошибка " + r.status); }
  async function getJSON(p, q, opt){ const r = await fetch(url(p, q), opt); if (!r.ok) throw new Error(await errText(r)); return r.json(); }
  const POST = {method: "POST", headers: {"Content-Type": "text/plain;charset=UTF-8"}};

  const api = {on, state: "idle", err: null, ios: !!(on && cfg.ios), noweb: !!(on && cfg.noweb)};
  if (!on) return api;
  /* iPhone: всё, что нужно рабочему потоку, — заранее в память и blob:, ссылки освобождаются после загрузки */
  async function blobs(a){
    if (!cfg.blob) return {a, free(){}};
    const out = Object.assign({}, a), made = [];
    const one = async (u, type) => {
      const r = await fetch(u);
      if (!r.ok) throw new Error(await errText(r));
      const b = URL.createObjectURL(new Blob([await r.arrayBuffer()], {type}));
      made.push(b); return b;
    };
    if (a.glue) out.glue = await one(a.glue, "text/javascript");
    if (a.wasm) out.wasm = await one(a.wasm, "application/wasm");
    if (a.model) out.model = await one(a.model, "application/octet-stream");
    if (a.lex) out.lex = await one(a.lex, "application/octet-stream");
    if (a.vocabs) out.vocabs = await Promise.all(a.vocabs.map(v => one(v, "application/octet-stream")));
    return {a: out, free(){ made.forEach(u => URL.revokeObjectURL(u)); }};
  }
  async function callB(op, args){ const b = await blobs(args); try { return await call(op, b.a); } finally { b.free(); } }

  api.fileUrl = p => url(p);
  api.url = (p, q) => url(p, q);
  const fq = from => from && from !== "en" ? {from} : null;
  api.status = () => getJSON("mt/status");
  api.download = from => getJSON("mt/download", fq(from), POST);
  api.remove = from => { reset(); return getJSON("mt/remove", fq(from), POST); };
  api.cacheGet = async k => { try { const r = await fetch(url("cache", {k})); return r.ok ? await r.json() : null; } catch (e){ return null; } };
  api.cachePut = (k, obj) => fetch(url("cache", {k}), Object.assign({body: JSON.stringify(obj)}, POST)).then(r => r.ok).catch(() => false);
  api.cacheDel = k => fetch(url("cache", {k, del: 1}), POST).then(r => r.ok).catch(() => false);
  api.cacheStat = () => getJSON("cache", {stat: 1});
  api.cacheClear = () => getJSON("cache", {clear: 1}, POST);
  /* страница из интернета для читалки: байты + кодировка, разбор — в KWeb */
  api.web = async u => {
    const r = await fetch(url("web", {u}));
    const buf = await r.arrayBuffer();
    if (!r.ok) throw new Error(new TextDecoder().decode(buf).trim().slice(0, 300) || ("ошибка " + r.status));
    return {buf, finalUrl: r.headers.get("X-Final-Url") || u, type: r.headers.get("X-Content-Type") || "", status: Number(r.headers.get("X-Status") || 200)};
  };

  /* ---- рабочий поток с движком ---- */
  function workerMain(){
    var Module = {}, service = null, models = {};
    var GEMM = {int8_prepare_a: "int8PrepareAFallback", int8_prepare_b: "int8PrepareBFallback", int8_prepare_b_from_transposed: "int8PrepareBFromTransposedFallback",
      int8_prepare_b_from_quantized_transposed: "int8PrepareBFromQuantizedTransposedFallback", int8_prepare_bias: "int8PrepareBiasFallback",
      int8_multiply_and_add_bias: "int8MultiplyAndAddBiasFallback", int8_select_columns_of_b: "int8SelectColumnsOfBFallback"};
    function get(u){ return fetch(u).then(function(r){ if (!r.ok) throw new Error("не загрузился " + u.split("?")[0].split("/").pop() + " (" + r.status + ")"); return r; }); }
    function aligned(buf, align){ var bytes = new Int8Array(buf), m = new Module.AlignedMemory(bytes.byteLength, align); m.getByteArrayView().set(bytes); return m; }
    function boot(u){
      return get(u.wasm).then(function(resp){
        return new Promise(function(resolve, reject){
          Module.instantiateWasm = function(info, accept){
            var gemm = {};
            Object.keys(GEMM).forEach(function(k){ var n = GEMM[k]; gemm[k] = function(){ return Module.asm[n].apply(null, arguments); }; });
            info.wasm_gemm = gemm;
            WebAssembly.instantiateStreaming(resp, info).then(function(x){ accept(x.instance); }, reject);
            return {};
          };
          Module.onRuntimeInitialized = resolve;
          Module.onAbort = function(w){ reject(new Error("движок остановился: " + w)); };
          Module.print = function(){}; Module.printErr = function(){};
          self.Module = Module;
          try { importScripts(u.glue); } catch (e){ reject(e); }
        });
      });
    }
    function load(u){
      return Promise.all([u.model, u.lex].concat(u.vocabs).map(function(x){ return get(x).then(function(r){ return r.arrayBuffer(); }); })).then(function(b){
        if (!service) service = new Module.BlockingService({cacheSize: 0});
        var vocabs = new Module.AlignedMemoryList();
        b.slice(2).forEach(function(v){ vocabs.push_back(aligned(v, 64)); });
        var gemm = /^int8shift(Alpha)?All$/.test(u.gemm || "") ? u.gemm : "int8shiftAlphaAll";
        var conf = ["beam-size: 1", "normalize: 1.0", "word-penalty: 0", "cpu-threads: 0", "gemm-precision: " + gemm, "skip-cost: true",
          "alignment: soft", "quiet: true", "quiet-translation: true", "max-length-break: 128", "mini-batch-words: 1024", "workspace: 128", "max-length-factor: 2.0"].join("\n") + "\n";
        models[u.key || "en"] = new Module.TranslationModel(conf, aligned(b[0], 256), aligned(b[1], 64), vocabs, null);
        return true;
      });
    }
    /* a.from: "en" — сразу en→ru; иначе через английский: X→en, затем en→ru */
    function tr(a){
      var texts = a.texts, from = a.from || "en", input = new Module.VectorString(), opts = new Module.VectorResponseOptions(), out = [], i;
      if (!models.en || (from !== "en" && !models[from])) throw new Error("модель перевода не загружена");
      for (i = 0; i < texts.length; i++){ input.push_back(texts[i]); opts.push_back({alignment: false, html: false, qualityScores: false}); }
      var res = from === "en" ? service.translate(models.en, input, opts) : service.translateViaPivoting(models[from], models.en, input, opts);
      input.delete(); opts.delete();
      for (i = 0; i < texts.length; i++) out.push(res.get(i).getTranslatedText());
      res.delete();
      return out;
    }
    self.onmessage = function(e){
      var m = e.data, p;
      try {
        if (m.op === "init") p = boot(m.args).then(function(){ return load(m.args); });
        else if (m.op === "load") p = load(m.args);
        else if (m.op === "boot") p = boot(m.args);
        else if (m.op === "tr") p = Promise.resolve(tr(m.args));
        else p = Promise.reject(new Error("unknown op"));
      } catch (err){ p = Promise.reject(err); }
      p.then(function(r){ self.postMessage({id: m.id, r: r}); }, function(err){ self.postMessage({id: m.id, err: String(err && err.message || err)}); });
    };
  }
  let W = null, ready = null, seq = 0;
  const wait = new Map(), pairs = {};
  function reset(){
    if (W){ try { W.terminate(); } catch (e){} }
    W = null; ready = null; api.state = "idle";
    Object.keys(pairs).forEach(k => delete pairs[k]);
    wait.forEach(p => p.rej(new Error("остановлено"))); wait.clear();
  }
  function call(op, args){ return new Promise((res, rej) => { const id = ++seq; wait.set(id, {res, rej}); W.postMessage({id, op, args}); }); }
  async function start(op){
    const st = await api.status().catch(() => ({}));
    const vocabs = [url("mt/model/vocab0")]; if ((st.vocabs || 1) > 1) vocabs.push(url("mt/model/vocab1"));
    W = new Worker(URL.createObjectURL(new Blob(["(" + workerMain.toString() + ")();"], {type: "text/javascript"})));
    W.onmessage = e => { const m = e.data, p = wait.get(m.id); if (!p) return; wait.delete(m.id); if (m.err) p.rej(new Error(m.err)); else p.res(m.r); };
    W.onerror = e => { e.preventDefault && e.preventDefault(); const err = new Error(e.message || "ошибка движка"); wait.forEach(p => p.rej(err)); wait.clear(); };
    const args = {key: "en", glue: url("mt/engine/glue.js"), wasm: url("mt/engine/engine.wasm"), model: url("mt/model/model"), lex: url("mt/model/lex"), vocabs, gemm: st.gemm || ""};
    if (op === "boot"){ delete args.model; delete args.lex; delete args.vocabs; }
    return callB(op, args);
  }
  /* загрузить движок и модель (один раз за запуск, ~1–3 с) */
  api.engine = function(){
    if (ready) return ready;
    api.state = "loading"; api.err = null;
    ready = start("init").then(() => { api.state = "ready"; return true; }, err => { reset(); api.state = "error"; api.err = err.message; throw err; });
    return ready;
  };
  /* проверка движка без модели (для самопроверки) */
  api.bootOnly = () => { reset(); return start("boot").then(r => { reset(); return r; }); };
  /* модель X→en для перевода через английский (загружается в тот же движок один раз) */
  api.pair = function(from){
    if (!from || from === "en") return api.engine();
    if (pairs[from]) return pairs[from];
    const p = pairs[from] = api.engine().then(async () => {
      const st = await api.status(), ps = st.pivots && st.pivots[from];
      if (!ps || ps.state !== "ready") throw new Error("не установлена модель " + from + "→en");
      const q = {from}, vocabs = [url("mt/model/vocab0", q)]; if ((ps.vocabs || 1) > 1) vocabs.push(url("mt/model/vocab1", q));
      return callB("load", {key: from, model: url("mt/model/model", q), lex: url("mt/model/lex", q), vocabs, gemm: ps.gemm || ""});
    });
    p.catch(() => { if (pairs[from] === p) delete pairs[from]; });
    return p;
  };
  api.translate = async (texts, from) => { from = from || "en"; await api.pair(from); return call("tr", {texts, from}); };
  api.stop = reset;
  return api;
})();

