/* Кушетка: разбор веб-страницы открытой книги или статьи в блоки для читалки (без скриптов, только текст).
   Блоки те же, что у встроенного учебника: h — заголовок, p — абзац, l — пункт списка, n — врезка,
   c — подпись к рисунку, t — таблица (ячейки через \u2028, строки через \u2029), a — ссылка на другую страницу,
   r — пункт списка литературы (его не переводим). */
window.KWeb = (function(){
  const DROP = ["script", "style", "noscript", "template", "iframe", "svg", "math annotation", "canvas", "video", "audio", "object", "embed", "form", "button", "input", "select", "textarea",
    "nav", "header", "footer", "aside", "menu", "dialog", "img", "picture", "[hidden]", "[aria-hidden='true']", "[role='navigation']", "[role='banner']", "[role='contentinfo']",
    ".visually-hidden", ".sr-only", ".screen-reader-text", ".noprint", ".no-print", ".mw-editsection", ".navbox", ".vertical-navbox", ".reflist", ".references", "sup.reference",
    ".toc", "#toc", ".printfooter", ".catlinks", "#siteSub", "#contentSub", ".mw-jump-link", ".mw-indicators", ".mw-authority-control", ".ambox",
    ".bk_prnt", ".bk_tt", "a.bibr", ".ref-list", "#reference-list", ".fn-group", ".pmc-sidenav", ".pmc-header", ".pmc-footer", ".ncbi-alert", ".jig-ncbiinpagenav-heading",
    ".nav-reading", ".a11y-toolbar", ".skip-link", ".share", ".social", ".sharing", ".breadcrumb", ".breadcrumbs", ".pagination", ".cookie", ".cookies", "#cookie-banner",
    ".mt-page-summary-hidden", ".mt-contentreuse-widget", "#pageNumberHolder", ".glossary-toggle", ".h5p-placeholder", ".interactive-content", ".textbox-caption-hidden"].join(",");
  const ROOTS = ["#mw-content-text .mw-parser-output", "#maincontent .main-content", ".main-content[itemprop='text']", "#maincontent .document", ".chapter-ugc", ".front-matter-ugc", ".back-matter-ugc", ".part-ugc",
    ".entry-content", ".chapter-content", "section.mt-content-container", ".mt-content-container", "#elm-main-content", "[data-type='page']", "section.article", "article", "main", "[role='main']", "#maincontent", "#content", ".content", "body"];
  const BLOCK = new Set(["p", "div", "section", "article", "main", "ul", "ol", "li", "h1", "h2", "h3", "h4", "h5", "h6", "table", "thead", "tbody", "tr", "td", "th", "figure", "figcaption",
    "blockquote", "pre", "dl", "dt", "dd", "details", "summary", "hr", "center", "caption", "address", "fieldset", "legend", "header", "footer", "aside", "nav"]);
  const clean = s => String(s || "").replace(/[    ]/g, " ").replace(/[​­]/g, "").replace(/\s+/g, " ").replace(/\s+([.,;:!?)\]])/g, "$1").replace(/([(\[])\s+/g, "$1").trim();
  const MAX_BLOCKS = 1600;

  function decode(buf, type){
    const bytes = new Uint8Array(buf);
    let cs = (/charset=([^;]+)/i.exec(type || "") || [])[1];
    if (!cs){ const head = new TextDecoder("latin1").decode(bytes.subarray(0, 4096)); cs = (/<meta[^>]+charset=["']?([a-z0-9_-]+)/i.exec(head) || [])[1]; }
    try { return new TextDecoder((cs || "utf-8").trim().toLowerCase()).decode(bytes); } catch (e){ return new TextDecoder("utf-8").decode(bytes); }
  }
  function textLen(el){ let n = 0; el.querySelectorAll("p, li, dd, td").forEach(p => { n += (p.textContent || "").length; }); return n; }
  function pickRoot(doc){
    let best = null, bestN = 0;
    for (const sel of ROOTS){
      let els; try { els = doc.querySelectorAll(sel); } catch (e){ continue; }
      for (const el of els){
        const n = textLen(el);
        if (n > 1200 && sel !== "body") return el;
        if (n > bestN){ best = el; bestN = n; }
      }
    }
    return best || doc.body;
  }
  function abs(href, base){ try { const u = new URL(href, base); return /^https?:$/.test(u.protocol) ? u.href.replace(/#.*$/, "") : ""; } catch (e){ return ""; } }
  function tableText(tb){
    const rows = [];
    tb.querySelectorAll("tr").forEach(tr => {
      if (tr.closest("table") !== tb) return;
      const cells = Array.from(tr.children).filter(c => /^(td|th)$/i.test(c.tagName)).map(c => clean(c.textContent).replace(/[\u2028\u2029]/g, " "));
      if (cells.some(Boolean)) rows.push(cells);
    });
    if (!rows.length) return "";
    const cap = tb.querySelector("caption");
    const title = cap ? clean(cap.textContent).replace(/: /g, " — ") : "";
    return (title ? title + ": " : "") + rows.map(r => r.join("\u2028")).join("\u2029");
  }

  function extract(buf, type, pageUrl){
    const html = typeof buf === "string" ? buf : decode(buf, type);
    const doc = new DOMParser().parseFromString(html, "text/html");
    const base = (doc.querySelector("base[href]") && abs(doc.querySelector("base[href]").getAttribute("href"), pageUrl)) || pageUrl;
    const lang = ((doc.documentElement.getAttribute("lang") || "").toLowerCase().split("-")[0]) || "";
    const metaT = doc.querySelector("meta[property='og:title']"), titleEl = doc.querySelector("title"), h1 = doc.querySelector("h1");
    const og = metaT ? metaT.getAttribute("content") : "", tt = titleEl ? titleEl.textContent : "", firstH1 = h1 ? h1.textContent : "";
    try { doc.querySelectorAll(DROP).forEach(el => el.remove()); } catch (e){}
    doc.querySelectorAll("sup").forEach(s => { if (/^[\s\[\]()\d,;–—-]*$/.test(s.textContent)) s.remove(); });
    doc.querySelectorAll("br").forEach(b => b.replaceWith(" "));
    if (doc.body) doc.body.querySelectorAll("p,div,li,td,th,h1,h2,h3,h4,h5,h6,dd,dt,section,article,tr,figcaption,caption,blockquote,ul,ol,dl,table").forEach(el => el.append(" "));
    const root = pickRoot(doc);
    const rh1 = root.querySelector("h1");
    let title = clean((rh1 && rh1.textContent) || og || tt || firstH1);
    title = title.replace(/\s+[-|–]\s+(NCBI Bookshelf|StatPearls.*|Physiopedia|LibreTexts|Medicine LibreTexts|PMC)$/i, "").slice(0, 300);
    const blocks = [];
    let inRefs = false;
    const REFS = /^(\d+(\.\d+)*\.?\s*)?(references?|bibliography|sources|further reading|external links|literature cited|works cited|citations|resources|литература|список литературы|источники)\s*:?$/i;
    const push = (k, t, href) => {
      t = k === "t" ? String(t || "").trim() : clean(t); if (!t || blocks.length >= MAX_BLOCKS) return;
      if (k !== "t" && t.length < 2) return;
      if (!blocks.length && k === "h" && t === title) return;
      if (k === "h") inRefs = REFS.test(t);
      else if (inRefs && k !== "t") k = "r";
      const prev = blocks[blocks.length - 1];
      if (prev && prev[0] === k && prev[1] === t) return;
      blocks.push(href ? [k, t, href] : [k, t]);
    };
    const linkOnly = el => {
      const as = el.querySelectorAll("a[href]"); if (as.length !== 1) return "";
      const t = clean(el.textContent), at = clean(as[0].textContent);
      if (!at || at.length < t.length * 0.7 || t.length > 200) return "";
      return abs(as[0].getAttribute("href"), base);
    };
    const hasBlock = el => { for (const c of el.children) if (BLOCK.has(c.tagName.toLowerCase())) return true; return false; };
    function walk(el){
      let buf = "";
      const flush = () => { if (clean(buf)) push("p", buf); buf = ""; };
      for (const n of el.childNodes){
        if (n.nodeType === 3){ buf += n.nodeValue; continue; }
        if (n.nodeType !== 1) continue;
        const tag = n.tagName.toLowerCase();
        if (!BLOCK.has(tag)){ buf += n.textContent; continue; }
        flush();
        block(n, tag);
      }
      flush();
    }
    function block(n, tag){
      if (/^h[1-6]$/.test(tag)){ push("h", n.textContent); return; }
      if (tag === "p"){ const href = linkOnly(n); if (href && clean(n.textContent).length < 150) push("a", n.textContent, href); else push(n.closest("blockquote, .textbox, .note, .box, aside") ? "n" : "p", n.textContent); return; }
      if (tag === "li"){ if (hasBlock(n)){ walk(n); return; } const href = linkOnly(n); if (href) push("a", n.textContent, href); else push("l", n.textContent); return; }
      if (tag === "figcaption" || tag === "caption"){ push("c", n.textContent); return; }
      if (tag === "table"){ const t = tableText(n); if (t) push("t", t); return; }
      if (tag === "blockquote"){ if (hasBlock(n)) walk(n); else push("n", n.textContent); return; }
      if (tag === "pre"){ push("p", n.textContent); return; }
      if (tag === "dt"){ push("h", n.textContent); return; }
      if (tag === "dd"){ if (hasBlock(n)) walk(n); else push("p", n.textContent); return; }
      if (tag === "hr" || tag === "thead" || tag === "tbody" || tag === "tr" || tag === "td" || tag === "th") return;
      walk(n);
    }
    walk(root);
    const host = (() => { try { return new URL(pageUrl).hostname.replace(/^www\./, ""); } catch (e){ return ""; } })();
    const words = blocks.reduce((s, b) => s + b[1].split(" ").length, 0);
    return {title: title || host, blocks, site: host, lang, words, url: pageUrl};
  }
  return {extract, decode};
})();

