/* Кушетка: полнотекстовый поиск и чтение «Библиотеки массажиста» (единица — страница PDF).
   Индекс собирается заранее (lib/build_mbindex.js) тем же стеммингом, что и поиск приложения.
   Файлы: idx/meta.json, idx/pages.bin, idx/sNN.bin, text/<id>.txt.gz.
   Windows: отдаёт помощник программы с диска пользователя; веб: файлы рядом со страницей. */
window.KLF = (function(){
  "use strict";
  let urlOf = null, meta = null, lens = null, readyP = null, failed = null, b64 = false;
  const shards = new Map(), books = new Map(), bookOrder = [];
  function fnv(s){ let h = 0x811c9dc5; for (let i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
  async function get(p){ const r = await fetch(urlOf(p)); if (!r.ok) throw new Error("нет файла " + p + " (" + r.status + ")"); return r; }
  /* веб-версия: двоичные файлы опубликованы как base64 в .txt (артефакты не отдают .bin и .gz) */
  async function getBuf(p){
    if (b64 && /\.(bin|gz)$/.test(p)){
      const s = (await (await get(p + ".txt")).text()).replace(/\s+/g, ""), bin = atob(s), u8 = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
      return u8.buffer;
    }
    return (await get(p)).arrayBuffer();
  }
  async function gunzipMaybe(buf){
    const u8 = new Uint8Array(buf);
    if (u8[0] !== 0x1f || u8[1] !== 0x8b) return new TextDecoder("utf-8").decode(u8);
    const ds = new Response(new Blob([u8]).stream().pipeThrough(new DecompressionStream("gzip")));
    return ds.text();
  }
  function setBase(fn, opt){ urlOf = fn; b64 = !!(opt && opt.b64); readyP = null; failed = null; meta = null; shards.clear(); books.clear(); bookOrder.length = 0; }
  let failedAt = 0;
  function ready(){
    if (!urlOf) return Promise.resolve(false);
    if (readyP) return readyP;
    if (failed && Date.now() - failedAt < 60000) return Promise.resolve(false);
    readyP = (async () => {
      meta = await (await get("idx/meta.json")).json();
      lens = new Uint16Array(await getBuf("idx/pages.bin"));
      meta.byId = new Map(meta.books.map(b => [b.id, b]));
      return true;
    })().catch(e => { failed = e.message || String(e); failedAt = Date.now(); readyP = null; return false; });
    return readyP;
  }
  async function shard(i){
    let p = shards.get(i); if (p) return p;
    p = (async () => {
      const buf = new Uint8Array(await getBuf("idx/s" + String(i).padStart(2, "0") + ".bin"));
      const dec = new TextDecoder("utf-8"), map = new Map();
      if (buf[0] !== 0x4b || buf[1] !== 0x4c || buf[2] !== 0x53) throw new Error("bad shard");
      const n = buf[4] | (buf[5] << 8) | (buf[6] << 16) | (buf[7] << 24);
      let o = 8;
      const vint = () => { let v = 0, m = 1, b; do { b = buf[o++]; v += (b & 127) * m; m *= 128; } while (b & 128); return v; };
      for (let t = 0; t < n; t++){
        const L = buf[o++]; const s = dec.decode(buf.subarray(o, o + L)); o += L;
        const df = vint(), start = o;
        for (let k = 0; k < df; k++){ vint(); o++; }
        map.set(s, {df, start, end: o});
      }
      return {buf, map};
    })();
    shards.set(i, p);
    return p;
  }
  async function postings(stem){
    const sh = await shard(fnv(stem) % meta.nshard), e = sh.map.get(stem);
    if (!e) return null;
    const ids = new Uint32Array(e.df), tf = new Uint8Array(e.df), buf = sh.buf; let o = e.start, prev = 0;
    for (let k = 0; k < e.df; k++){ let v = 0, m = 1, b; do { b = buf[o++]; v += (b & 127) * m; m *= 128; } while (b & 128); prev += v; ids[k] = prev; tf[k] = buf[o++]; }
    return {ids, tf, df: e.df};
  }
  function bookOfPage(pid){
    const B = meta.books; let lo = 0, hi = B.length - 1;
    while (lo < hi){ const mid = (lo + hi + 1) >> 1; if (B[mid].off <= pid) lo = mid; else hi = mid - 1; }
    return B[lo];
  }
  /* concepts: [{alts:[{seq:[stems], w}]}] из KSearch.parse; minus: [stems]; filter(bookId) → bool */
  async function search(concepts, opt){
    opt = opt || {};
    if (!(await ready())) return null;
    const N = meta.N, avg = meta.avgdl || 200, k1 = 1.2, b = 0.75;
    const cache = new Map();
    const P = async s => { if (!cache.has(s)) cache.set(s, await postings(s)); return cache.get(s); };
    const idf = df => Math.log(1 + (N - df + 0.5) / (df + 0.5));
    const cm = [];
    for (const c of concepts){
      const m = new Map();
      for (const a of c.alts){
        const lists = [];
        for (const s of a.seq){ const p = await P(s); if (!p){ lists.length = 0; break; } lists.push(p); }
        if (!lists.length) continue;
        lists.sort((x, y) => x.df - y.df);
        const base = lists[0], sets = lists.slice(1).map(l => { const mm = new Map(); for (let k = 0; k < l.df; k++) mm.set(l.ids[k], l.tf[k]); return mm; });
        const w = a.w || 1;
        for (let k = 0; k < base.df; k++){
          const pid = base.ids[k]; let sc = 0, ok = true;
          const dl = lens[pid] || avg, norm = k1 * (1 - b + b * dl / avg);
          sc += idf(base.df) * base.tf[k] * (k1 + 1) / (base.tf[k] + norm);
          for (let j = 0; j < sets.length; j++){ const t = sets[j].get(pid); if (t == null){ ok = false; break; } sc += idf(lists[j + 1].df) * t * (k1 + 1) / (t + norm); }
          if (!ok) continue;
          sc *= w;
          if (sc > (m.get(pid) || 0)) m.set(pid, sc);
        }
      }
      cm.push(m);
    }
    const used = cm.filter(m => m.size).length || 1;
    const tot = new Map(), hits = new Map();
    cm.forEach(m => m.forEach((v, pid) => { tot.set(pid, (tot.get(pid) || 0) + v); hits.set(pid, (hits.get(pid) || 0) + 1); }));
    let minus = null;
    if (opt.minus && opt.minus.length){ minus = new Set(); for (const s of opt.minus){ const p = await P(s); if (p) for (const id of p.ids) minus.add(id); } }
    const res = [];
    tot.forEach((v, pid) => {
      if (minus && minus.has(pid)) return;
      const bk = bookOfPage(pid);
      if (opt.filter && !opt.filter(bk.id)) return;
      const cov = hits.get(pid) / used;
      res.push({pid, id: bk.id, p: pid - bk.off, score: v * (0.3 + 0.7 * cov * cov), cov});
    });
    res.sort((x, y) => y.score - x.score);
    return {hits: res.slice(0, opt.limit || 400), total: res.length};
  }
  /* текст книги: массив страниц */
  async function bookPages(id){
    if (books.has(id)) return books.get(id);
    const p = (async () => {
      const txt = await gunzipMaybe(await getBuf("text/" + id + ".txt.gz"));
      const pages = txt.split("\f"); if (pages.length && !pages[pages.length - 1].trim()) pages.pop();
      return pages;
    })();
    books.set(id, p); bookOrder.push(id);
    while (bookOrder.length > 8){ const old = bookOrder.shift(); if (old !== id) books.delete(old); }
    p.catch(() => books.delete(id));
    return p;
  }
  /* абзацы страницы: пустая строка — граница, переносы по слогам склеиваются */
  function paras(t){
    return String(t || "").replace(/\r/g, "").split(/\n\s*\n/).map(p => p.replace(/([a-zа-яёіїєґà-ÿ])-\n\s*([a-zа-яёіїєґà-ÿ])/g, "$1$2").replace(/\s*\n\s*/g, " ").replace(/\s{2,}/g, " ").trim()).filter(p => p.length > 1);
  }
  /* has/ocr — по индексу на диске: так новые тексты (например, распознанные сканы) появляются без пересборки программы */
  /* любой файл библиотеки текстом (.gz распаковывается): база продуктов food/db.json.gz */
  async function file(p){ if (!urlOf) throw new Error("файлы библиотеки недоступны"); return gunzipMaybe(await getBuf(p)); }
  return {setBase, ready, search, bookPages, paras, file, get meta(){ return meta; }, get error(){ return failed; }, get loaded(){ return !!(meta && meta.byId); },
    has: id => !!(meta && meta.byId && meta.byId.has(id)), ocr: id => !!(meta && meta.byId && meta.byId.has(id) && meta.byId.get(id).o)};
})();

;
