  const it = {ex, alts: pick.alts, subst: pick.subst, pat: s.pat, pair: s.pair, sets, reps, rir, pct, pctText: s.pctTextW ? s.pctTextW[wi] : s.pctText, kg, kgEst, tempo: s.tempo, rest, minutes, note: s.note || (ex && ex.note), kind: s.kind};
